const num = (v, d = 0) => (v === null || v === undefined || Number.isNaN(Number(v)) ? '-' : Number(v).toLocaleString('en-US', { maximumFractionDigits: d }));
const cell = (s) => String(s ?? '').replaceAll('|', '\\|').replaceAll('\n', ' ').replaceAll('<', '&lt;').replaceAll('{{', '&#123;&#123;');
const esc = (s) => String(s).replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;');

export function loadStrongholds(all) {
  return {
    rows: all('SELECT * FROM stronghold ORDER BY sort'),
    stages: all('SELECT * FROM stronghold_stage ORDER BY stronghold_id, stage'),
    texts: all('SELECT * FROM stronghold_stage_text'),
    terrain: all('SELECT * FROM stronghold_terrain_type ORDER BY sort'),
    floors: all('SELECT * FROM stronghold_floor ORDER BY stronghold_id, sort'),
  };
}

// Returns [{ rel, title, content, fm }] for one locale.
export function strongholdPages({ data, ko, g, P, BASE, factions, stations }) {
  const S = ko ? T.ko : T.en;
  const out = [];
  const textOf = new Map(data.texts.map((t) => [`${t.stage}:${t.variant}`, t]));
  const terrainOf = new Map(data.terrain.map((t) => [t.id, t]));
  const stagesOf = new Map(); data.stages.forEach((s) => { if (!stagesOf.has(s.stronghold_id)) stagesOf.set(s.stronghold_id, []); stagesOf.get(s.stronghold_id).push(s); });
  const floorsOf = new Map(); data.floors.forEach((f) => { if (!floorsOf.has(f.stronghold_id)) floorsOf.set(f.stronghold_id, []); floorsOf.get(f.stronghold_id).push(f); });
  const byStation = new Map(data.rows.map((r) => [r.station_id, r]));
  const stationById = new Map(stations.map((s) => [s.id, s]));
  const fName = (id) => { const x = factions.find((f) => f.id === id); return x ? g(x, 'name') : id; };
  const tLabel = (id) => (terrainOf.get(id) ? g(terrainOf.get(id), 'label') : id);
  const stageText = (r, k) => textOf.get(`${k}:${r.faction_id === 'arc' && k >= 4 ? 'arc' : 'common'}`);
  const stageName = (r, k) => g(stageText(r, k), 'name');
  const sName = (r) => g(r, 'name');
  const link = (r) => `[${cell(sName(r))}](${P(`${STRONGHOLD_ROUTE}${r.id}/`)})`;
  const stationRef = (id) => { const sh = byStation.get(id); if (sh) return link(sh); const s = stationById.get(id); return s ? cell(g(s, 'name')) : cell(id); };
  const sorted = [...data.rows].sort((a, b) => sName(a).localeCompare(sName(b), ko ? 'ko' : 'en'));
  const methodLink = `[${S.methodLink}](${P(STRONGHOLD_GDD)})`;

  // index
  const factionIds = ['government', 'free-city', 'arc'].filter((id) => data.rows.some((r) => r.faction_id === id));
  const countBy = (key) => { const m = new Map(); data.rows.forEach((r) => m.set(key(r), (m.get(key(r)) ?? 0) + 1)); return m; };
  const stageCounts = countBy((r) => r.start_stage); const terrCounts = countBy((r) => r.terrain_primary);
  const idx = [`# ${S.title}`, '', `::: warning ${S.provisional}`, S.provNote, ':::', '', S.lead(data.rows.length), '', `${S.method}: ${methodLink}`, '',
    `- ${S.byStage}: ${[...stageCounts].sort((a, b) => a[0] - b[0]).map(([k, n]) => `${k} ${stageName({ faction_id: 'government' }, k)} ${n}`).join(' · ')}`,
    `- ${S.byTerrain}: ${data.terrain.filter((t) => terrCounts.get(t.id)).map((t) => `${g(t, 'label')} ${terrCounts.get(t.id)}`).join(' · ')}`, ''];
  for (const fid of factionIds) {
    const rs = sorted.filter((r) => r.faction_id === fid);
    idx.push(`## ${fName(fid)}`, '', S.stationsN(rs.length), '', `| ${S.cols.station} | ${S.cols.district} | ${S.cols.start} | ${S.cols.terrain} | ${S.cols.pop} |`, '| --- | --- | --- | --- | ---: |');
    rs.forEach((r) => idx.push(`| ${link(r)} | ${cell(g(r, 'district'))} | ${r.start_stage} ${cell(stageName(r, r.start_stage))} | ${cell(tLabel(r.terrain_primary))} | ${num(r.population)} |`));
    idx.push('');
  }
  out.push({ rel: `${STRONGHOLD_ROUTE}index.md`, title: S.title, content: idx.join('\n'), fm: { outline: [2, 2] } });

  // one page per station
  for (const r of data.rows) {
    const name = sName(r);
    const tr = JSON.parse(r.terrain_json);
    const per = r.perimeter_json ? JSON.parse(r.perimeter_json) : null;
    const tags = JSON.parse(r.terrain_tags);
    const neigh = JSON.parse(r.neighbour_ids);
    const st = stagesOf.get(r.id) ?? [];
    const L = [`# ${S.stationTitle(name)}`, '', `::: warning ${S.provisional}`, S.provNote, ':::', '',
      `| ${S.field} | ${S.value} |`, '| --- | --- |',
      `| ${S.faction} | [${cell(fName(r.faction_id))}](${P(`wiki/factions/${r.faction_id}/`)}) |`,
      `| ${S.district} | ${cell(g(r, 'district'))} |`,
      `| ${S.start} | ${r.start_stage} · ${cell(stageName(r, r.start_stage))} |`,
      `| ${S.terrain} | ${cell(tLabel(r.terrain_primary))} |`,
      `| ${S.tags} | ${tags.map((t) => cell(tLabel(t))).join(', ')} |`,
      `| ${S.pop} | ${num(r.population)} |`,
      r.shelter_station_id ? `| ${S.shelter} | ${stationRef(r.shelter_station_id)} |` : null,
      neigh.length ? `| ${S.neighbours} | ${neigh.map(stationRef).join(', ')} |` : null,
      '', `${S.method}: ${methodLink} · [${S.allStrongholds}](${P(STRONGHOLD_ROUTE)})`, ''].filter((x) => x !== null);
    if (r.img_ground || r.img_under) {
      L.push(`## ${S.plans}`, '');
      if (S.planNote) L.push(S.planNote, '');
      const fig = (file, w, h, alt) => `<figure class="stronghold-plan"><a href="${BASE}${STRONGHOLD_IMG_DIR}/${file}" target="_blank" rel="noopener"><img src="${BASE}${STRONGHOLD_IMG_DIR}/${file}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy" decoding="async"></a></figure>`;
      if (r.img_ground) L.push(fig(r.img_ground, r.img_ground_w, r.img_ground_h, S.altGround(name)), '');
      if (r.img_under) L.push(fig(r.img_under, r.img_under_w, r.img_under_h, S.altUnder(name)), '');
    }
    L.push(`## ${S.reading}`, '', `| ${S.field} | ${S.value} |`, '| --- | ---: |');
    const R = S.r;
    const rr = (k, d = 0) => (tr[k] === undefined || tr[k] === null ? null : `| ${R[k]} | ${num(tr[k], d)} |`);
    [rr('relief_m', 1), rr('station_elev', 1), tr.elev_min !== undefined && tr.elev_min !== null ? `| ${R.elev} | ${num(tr.elev_min, 1)} - ${num(tr.elev_max, 1)} |` : null,
      rr('slope_p90_pct', 1), rr('steep_share', 3), rr('river_dist_m'), rr('river_m2_300'), rr('rail_m2_300'), rr('cutfill_m_300'), rr('levee_m_300'), rr('wall_m_300'),
      rr('road_share', 3), rr('bld_count'), rr('bld_cover', 3), rr('floors_mean_w', 1), rr('highrise_share', 3), rr('apt_count'), rr('small_bld_share', 3), rr('roof_max_m', 1),
      rr('ug_floor_m2'), rr('depth_max_m', 1), rr('underpass_m2')].filter(Boolean).forEach((x) => L.push(x));
    if (tr.scores) L.push(`| ${R.scores} | ${data.terrain.map((t) => `${cell(g(t, 'label'))} ${num(tr.scores[t.id] ?? 0, 2)}`).join(', ')} |`);
    L.push('');
    const I = S.i;
    L.push(`## ${S.inputs}`, '', `| ${S.field} | ${S.value} |`, '| --- | ---: |',
      `| ${I.P} | ${num(r.population)} |`, `| ${I.F} | ${num(r.f_station_m2)} |`, `| ${I.Fsrc} | ${cell(g(r, 'f_station_src'))} |`, `| ${I.E} | ${r.e_used} / ${r.e_hidden} / ${r.e_sealed} |`, `| ${I.C} | ${r.tunnel_cuts} |`,
      `| ${I.V} | ${r.vents} (${r.vents_measured ? I.Vm : I.Ve}) |`, `| ${I.Q} | ${num(r.q_m3h)} |`,
      `| ${I.fuel} | ${num(r.fuel_kg, 1)} |`,
      `| ${I.L} | ${num(r.l_surface_m)} |`, `| ${I.Fb} | ${num(r.f_bld_m2)} |`, `| ${I.Ft} | ${num(r.f_tunnel_m2)} |`, `| ${I.kw} | ${num(r.k_w, 2)} |`, `| ${I.M} | ${num(r.m_share, 2)} |`,
      `| ${I.B} | ${num(r.building_count)} |`, `| ${I.X} | ${num(r.exit_count)} |`, '');
    if (per) {
      const Pp = S.p;
      L.push(`## ${S.perimeter}`, '', `| ${S.field} | ${S.value} |`, '| --- | ---: |');
      for (const k of ['length', 'blocks', 'area_m2', 'guards_need', 'guards_avail', 'n_cuts', 'outposts', 'watch_top_m']) if (per[k] !== undefined && per[k] !== null) L.push(`| ${Pp[k]} | ${num(per[k], 1)} |`);
      if (per.share) L.push(`| ${Pp.share} | ${Object.entries(per.share).map(([k, v]) => `${S.kinds[k] ?? k} ${num(v)}`).join(', ')} |`);
      L.push('');
    }
    const fl = floorsOf.get(r.id) ?? [];
    if (fl.length) {
      const F = S.fl;
      L.push(`## ${S.floors}`, '', ko ? `| ${F.floor} | ${F.depth} | ${F.area} | ${F.rail} | ${F.use} |` : `| ${F.floor} | ${F.depth} | ${F.area} | ${F.rail} |`, ko ? '| --- | ---: | ---: | --- | --- |' : '| --- | ---: | ---: | --- |');
      fl.forEach((f) => L.push(`| ${cell(f.floor)} | ${num(f.depth_m, 1)} | ${num(f.walk_m2)} | ${f.has_rail ? S.yes : ''} |${ko ? ` ${cell(f.use_ko)} |` : ''}`));
      L.push('');
    }
    const C = S.sc;
    const stCell = (s) => (s.stage === r.start_stage ? `**${s.stage}**${S.startMark}` : s.stage);
    const cb = (v) => S.capBy[v] ?? v;
    L.push(`## ${S.stages}`, '', S.capNote, '', `### ${S.stagesCap}`, '',
      `| ${S.stage} | ${S.name} | ${C.floor} | ${C.cap} | ${C.live} | ${C.status} | ${C.limit} | ${C.air} |`,
      '| --- | --- | ---: | ---: | ---: | --- | ---: | --- |');
    st.forEach((s) => L.push(`| ${stCell(s)} | ${cell(stageName(r, s.stage))} | ${num(s.floor_m2)} | ${num(s.capacity)} (${cb(s.cap_by_max)}) | ${num(s.living_capacity)} (${cb(s.cap_by)}) | ${s.over_max ? S.st.overflow : s.over_living ? S.st.over : S.st.ok} | ${num(s.overcrowd_limit)} | ${S.airMode(s.air_speed, s.stage)} |`));
    L.push('', `### ${S.stagesWatch}`, '',
      `| ${S.stage} | ${C.gs} | ${C.ge} | ${C.mob} | ${C.def} | ${C.food} | ${C.fuel} | ${C.line} | ${C.towers} |`,
      '| --- | ---: | ---: | ---: | --- | ---: | ---: | ---: | ---: |');
    st.forEach((s) => L.push(`| ${stCell(s)} | ${num(s.guard_standing)} | ${num(s.guard_emergency)} | ${num(s.mobilisable)} | ${s.defensible ? S.yes : S.no} | ${num(s.food_t, 1)} | ${num(s.fuel_t, 1)} | ${s.surface_line_m ? `${num(s.surface_line_real_m)} / ${num(s.surface_line_m)}` : '-'} | ${num(s.watchtowers)} |`));
    L.push('');
    st.forEach((s) => {
      const t = stageText(r, s.stage);
      L.push(`### ${S.stage} ${s.stage}: ${cell(g(t, 'name'))}`, '', `- **${S.works}:** ${g(t, 'works')}`);
      const tw = g(s, 'terrain_works'); if (tw) L.push(`- **${S.terrainWorks}:** ${tw}`);
      L.push(`- **${S.facilities}:** ${g(t, 'facilities')}`, `- **${S.labor}:** ${g(t, 'labor')}`, `- **${S.duration}:** ${g(t, 'duration')}`, `- **${S.entry}:** ${g(t, 'entry')}`, '');
    });
    L.push(`## ${S.source}`, '', S.sourceText, '');
    out.push({ rel: `${STRONGHOLD_ROUTE}${r.id}/index.md`, title: S.stationTitle(name), content: L.join('\n'), fm: { outline: [2, 2] } });
  }
  return { pages: out, title: S.title };
}
